async function seedAuditEvents(
  subjectId: string,
  count: number,
  opts: {
    idPrefix: string;
    action: string;
    chunkSize?: number;
  }
): Promise<number> {
  // Helper used only by the 413 test below. Returns the number of rows
  // actually inserted (for the test's own assertion / cleanup math).
  // Not used by the happy-path / auth / validation / audit-row tests
  // — those use small fixed seeds.
  const CHUNK = opts.chunkSize ?? 1000;
  let inserted = 0;
  for (let start = 0; start < count; start += CHUNK) {
    const end = Math.min(start + CHUNK, count);
    const batch: Array<typeof auditEvents.$inferInsert> = [];
    for (let i = start; i < end; i++) {
      batch.push({
        id: `${opts.idPrefix}-${i.toString().padStart(7, "0")}`,
        actorUserId: subjectId,
        actorRole: "STUDENT",
        action: opts.action,
        targetType: "user",
        targetId: subjectId,
        createdAt: new Date(Date.now() - (count - i) * 1000),
      });
    }
    await db.insert(auditEvents).values(batch);
    inserted += batch.length;
  }
  return inserted;
}

